/**
 * @method
 * @name setCorpInfo
 * @description set Corp Info 처리
 * @param {String} isurCd isurCd
 * @param {String} kisComCd kisComCd
 * @param {String} repIsuCd repIsuCd
 * @param {String} repIsuSrtCd repIsuSrtCd
 * @param {String} comNm comNm
 * @param {*} comAbbrv comAbbrv
 * @param {*} isurSymbl isurSymbl
 * @param {*} fssUnqNo fssUnqNo
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setCorpInfo = async function (isurCd, kisComCd, repIsuCd, repIsuSrtCd, comNm, comAbbrv, isurSymbl, fssUnqNo) {
    let str = "";
    str += "isurCd : " + isurCd + "\n";
    str += "kisComCd : " + kisComCd + "\n";
    str += "repIsuCd : " + repIsuCd + "\n";
    str += "repIsuSrtCd : " + repIsuSrtCd + "\n";
    str += "comNm : " + comNm + "\n";
    str += "comAbbrv : " + comAbbrv + "\n";
    str += "isurSymbl : " + isurSymbl + "\n";
    str += "fssUnqNo : " + fssUnqNo + "\n";
    const returnKey = '' + dma_pageContext.get("returnKey") + '';
    const obj = ((($c.data.getParameter() && typeof $c.data.getParameter() === 'object' && Object.keys($c.data.getParameter()).length) ? $c.data.getParameter() : scwin.openerScwin()).Potential).Provider;
    const frameId = obj.ActiveFrame.FrameID;
    const frame = obj.Provider(frameId).ActiveFrame;
    try {
        frame.setCorpInfo(isurCd, kisComCd, repIsuCd, repIsuSrtCd, comNm, comAbbrv, isurSymbl, fssUnqNo, returnKey);
        $c.win.closePopup();
    } catch (e) { $c.exception.handleError(e, { notify: 'none', context: 'jldfil00029' });
        await $c.win.alert("<ERROR>\n\n" + "부모창을 찾을 수가 없습니다. \n\n" + str);
    }
};

/**
 * @method
 * @name opener
 * @description 부모 화면 scope(browserPopup/pageFramePopup 공통 — $c.win.getOpenerScope). 단독 진입이거나 부모가 닫혀 없으면
 * @returns {Object} 부모 화면 scope 또는 빈 scope
 * @hidden N
 */
scwin.opener = function () {
    const scope = ($c.win && $c.win.getOpenerScope) ? $c.win.getOpenerScope() : null;
    return scope || { getComponentById: function () { return null; }, scwin: {} };
};

/**
 * @method
 * @name openerScwin
 * @description 부모 화면의 scwin(함수·전역 접근용). 부모가 없으면 빈 객체
 * @returns {Object} 부모 scwin 또는 {}
 * @hidden N
 */
scwin.openerScwin = function () {
    return scwin.opener().scwin || {};
};
